"""E2: lock helpers keep tested versions and hash only this platform's files."""

import sys
from hashlib import sha256
from pathlib import Path

import pytest
from packaging.version import Version

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "scripts/deps"))

from locks import downloaded_hashes, hash_pins, main, parse_lock, pins

A, B, C = "a" * 64, "b" * 64, "c" * 64

# pip-compile output without --generate-hashes, as update_locks.sh writes it.
PINS = """#
# This file is autogenerated by pip-compile with Python 3.12
#
Pillow==13.0.0
    # via -r requirements/ml.txt
torch==2.6.0+cpu
    # via -r requirements/ml.txt
"""


def test_parse_lock_reads_multiline_and_compact_entries():
    compiled = f"Pillow==13.0.0 \\\n    --hash=sha256:{A} \\\n    --hash=sha256:{B}\n"
    compact = f"# header\nzope.interface==7.0 --hash=sha256:{C}\n"

    assert parse_lock(compiled) == {"pillow": ("Pillow", "13.0.0", [A, B])}
    assert parse_lock(compact) == {"zope-interface": ("zope.interface", "7.0", [C])}


def test_pins_later_lock_wins_and_excluded_names_move():
    old = f"pillow==12.3.0 --hash=sha256:{A}\nnumpy==2.5.4 --hash=sha256:{B}\n"
    new = f"Pillow==13.0.0 --hash=sha256:{C}\n"

    assert pins([old, new], set()) == ["numpy==2.5.4", "Pillow==13.0.0"]
    assert pins([old, new], {"pillow"}) == ["numpy==2.5.4"]


def test_hash_pins_uses_the_downloaded_files_hashes():
    found = {
        ("pillow", Version("13.0.0")): [A],
        ("torch", Version("2.6.0+cpu")): [B, C],
    }

    assert hash_pins(PINS, found, ["header line", ""]) == [
        "# header line",
        "#",
        f"Pillow==13.0.0 --hash=sha256:{A}",
        f"torch==2.6.0+cpu --hash=sha256:{B} --hash=sha256:{C}",
    ]


def test_hash_pins_refuses_a_pin_with_no_downloaded_file():
    with pytest.raises(ValueError, match="torch==2.6.0\\+cpu"):
        hash_pins(PINS, {("pillow", Version("13.0.0")): [A]}, [])


def test_main_hash_writes_the_lock_from_downloaded_wheels_and_sdists(tmp_path):
    downloads = tmp_path / "downloads"
    downloads.mkdir()
    (downloads / "pillow-13.0.0-cp312-cp312-manylinux_2_28_x86_64.whl").write_bytes(
        b"w"
    )
    (downloads / "torch-2.6.0+cpu.tar.gz").write_bytes(b"s")
    pins_file = tmp_path / "pins.txt"
    pins_file.write_text(PINS, encoding="utf-8")
    output = tmp_path / "ml.lock"

    assert downloaded_hashes(downloads) == {
        ("pillow", Version("13.0.0")): [sha256(b"w").hexdigest()],
        ("torch", Version("2.6.0+cpu")): [sha256(b"s").hexdigest()],
    }
    argv = ["hash", str(pins_file), "--downloads", str(downloads)]
    assert main([*argv, "--header", "h", "--output", str(output)]) == 0
    assert output.read_text(encoding="utf-8").splitlines() == [
        "# h",
        f"Pillow==13.0.0 --hash=sha256:{sha256(b'w').hexdigest()}",
        f"torch==2.6.0+cpu --hash=sha256:{sha256(b's').hexdigest()}",
    ]
